{"thought": "The specification is clear: compute the due date by adding `net_days` to `invoice_date`. If the result falls on a Saturday or Sunday, move it to the following Monday. I also need to handle negative `net_days` and invalid date strings by raising `ValueError`. I'll use the `datetime` module to implement this.", "action": {"tool": "write_file", "args": {"path": "src/ledgerlib/due_date.py", "content": "from __future__ import annotations

from datetime import datetime, timedelta


def due_date(invoice_date: str, net_days: int) -> str:
    """
    Return the payment due date of an invoice dated `invoice_date` with payment terms
    of `net_days` days ("NET 30" -> 30, "due on receipt" -> 0).

    Dates are ISO strings "YYYY-MM-DD"; the result is an ISO string as well. Raises
    ValueError if `net_days` is negative or `invoice_date` is not a valid ISO date.

    Example:
        due_date("2024-01-10", 30) == "2024-02-09"
    """
    if net_days < 0:
        raise ValueError("net_days cannot be negative")

    try:
        date_obj = datetime.fromisoformat(invoice_date).date()
    except ValueError as e:
        raise ValueError(f"Invalid ISO date: {invoice_date}") from e

    target_date = date_obj + timedelta(days=net_days)

    # 5 is Saturday, 6 is Sunday
    if target_date.weekday() == 5:
        target_date += timedelta(days=2)
    elif target_date.weekday() == 6:
        target_date += timedelta(days=1)

    return target_date.isoformat()
"}}, "messages": []}

