def format_cents(cents: int, symbol: str = "") -> str:
    """
    Format integer cents as '1,234.56' with an optional currency symbol.

    With a currency symbol, the minus sign of a negative amount goes in front of the
    symbol: format_cents(-500, "$") == "-$5.00", never "$-5.00".
    """
    is_negative = cents < 0
    abs_cents = abs(cents)
    dollars = abs_cents // 100
    cents_part = abs_cents % 100

    formatted_amount = f"{dollars:,}.{cents_part:02d}"

    if symbol:
        if is_negative:
            return f"-{symbol}{formatted_amount}"
        else:
            return f"{symbol}{formatted_amount}"
    else:
        return f"-{formatted_amount}" if is_negative else formatted_amount
"}}, "messages": []}

